//! Plugin-declared kinds against usd-core 26.8's `KindRegistry`.
//!
//! Three plugins declare `Kinds`: `fixtures/custom_kinds` (kinds alone,
//! generated by this crate's build script with `generate_kind_library`),
//! the `lab` schema library (`layerstack_custom_schemas::lab`, whose module
//! `rust_module` generates from its `plugInfo.json`), and
//! `fixtures/custom_kinds/rejected`, whose declarations OpenUSD mostly
//! refuses, read here with `layerstack_schemagen::kinds::read`.
//! `fixtures/custom_kinds/oracle.json` (`scripts/plugin_kinds_oracle.py`)
//! records the errors OpenUSD raises registering them, the kinds and base
//! kinds it registers, and `IsA` over every pair; the registry built here
//! must agree, and must report as issues what OpenUSD registers but cannot
//! answer (`IsA` around a cycle of bases never returns there).
//!
//! Spec: AOUSD Core §7.6.2.4.4, §11.4. OpenUSD: `KindRegistry`
//! (`pxr/usd/kind/registry.cpp`).

#![allow(missing_docs, reason = "integration tests")]

pub mod generated {
    include!(concat!(env!("OUT_DIR"), "/custom_kinds.rs"));
}

use layerstack::{FieldValue, InMemoryStore, Layer, LayerId, PrimSpec, Stage, StageOptions, Value};
use layerstack_schemas::Scene;
use layerstack_schemas::kind::KindRegistry;

/// The oracle replay, which needs the schema generator and the lab
/// library: like them, it does not build for wasm.
#[cfg(not(target_arch = "wasm32"))]
mod oracle {
    use std::collections::BTreeMap;

    use layerstack_conformance::workspace_root;
    use layerstack_custom_schemas::lab;
    use layerstack_schemagen::kinds::{KindRejection, read};
    use layerstack_schemas::kind::{KindIssue, KindRegistry};
    use serde::Deserialize;

    use super::generated;

    #[derive(Deserialize)]
    struct Oracle {
        errors: Vec<String>,
        kinds: Vec<String>,
        base_kinds: BTreeMap<String, String>,
        is_a: BTreeMap<String, Vec<String>>,
        hangs: BTreeMap<String, Vec<String>>,
    }

    fn fixture(path: &str) -> String {
        let path = workspace_root()
            .join("layerstack_conformance/fixtures")
            .join(path);
        std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()))
    }

    /// The message OpenUSD's `KindRegistry` raises for `rejection` of `kind`.
    fn openusd_message(kind: &str, rejection: &KindRejection) -> String {
        match rejection {
            KindRejection::NotAnObject => format!("Expected dict for kind '{kind}'"),
            KindRejection::BaseNotAString => "Expected string for baseKind".into(),
            KindRejection::InvalidName => format!("Invalid kind: '{kind}'"),
            KindRejection::BuiltIn | KindRejection::AlreadyDeclared { .. } => {
                format!("Kind '{kind}' has already been registered")
            }
            other => panic!("OpenUSD reports nothing for {other:?}"),
        }
    }

    #[test]
    fn plugin_kinds_answer_as_openusd_does() {
        let oracle: Oracle = serde_json::from_str(&fixture("custom_kinds/oracle.json")).unwrap();
        let mut kinds = KindRegistry::new();
        assert!(generated::register(&mut kinds).is_empty());
        assert!(lab::register_kinds(&mut kinds).is_empty());
        // The rejected plugin, read as one set with the first, which declares
        // `stack_leaf` before it.
        let (first, rejected) = (
            fixture("custom_kinds/plugInfo.json"),
            fixture("custom_kinds/rejected/plugInfo.json"),
        );
        let declarations = read([
            ("custom_kinds", first.as_str()),
            ("rejected", rejected.as_str()),
        ])
        .expect("both are plugInfo.json files");
        let mut messages = Vec::new();
        for declaration in &declarations.accepted {
            if declaration.plugin.starts_with("rejected") {
                kinds
                    .register(&declaration.kind, declaration.base.as_deref())
                    .expect("an accepted declaration registers");
            }
        }
        for error in &declarations.rejected {
            assert!(error.plugin.starts_with("rejected: "), "{error}");
            let kind = error.kind.as_deref().expect("a declaration");
            messages.push(openusd_message(kind, &error.reason));
        }
        messages.sort();
        assert_eq!(messages, oracle.errors, "what OpenUSD refuses");

        let mut registered: Vec<&str> = kinds.kinds().collect();
        registered.sort_unstable();
        assert_eq!(registered, oracle.kinds);
        for (kind, base) in &oracle.base_kinds {
            assert_eq!(kinds.base_kind(kind).unwrap_or(""), base, "{kind}");
        }
        let mut failures = Vec::new();
        for (kind, bases) in &oracle.is_a {
            for target in oracle.is_a.keys() {
                let ours = kinds.is_a(kind, target);
                // Where OpenUSD's walk never returns, this answers `false`.
                let expected = bases.contains(target);
                if ours != expected {
                    failures.push(format!("IsA({kind}, {target}): ours {ours}"));
                }
            }
        }
        assert!(failures.is_empty(), "{}", failures.join("\n"));

        // What OpenUSD registers and cannot answer for: a base that is no
        // kind, and the cycle every hanging walk reaches.
        let issues = kinds.issues();
        assert!(issues.contains(&KindIssue::UnknownBase {
            kind: "stack_orphan".into(),
            base: "stack_missing".into(),
        }));
        let cycles: Vec<&Vec<String>> = issues
            .iter()
            .filter_map(|issue| match issue {
                KindIssue::Cycle { kinds } => Some(kinds),
                _ => None,
            })
            .collect();
        assert_eq!(
            cycles,
            [&vec![
                "stack_ring_a".to_string(),
                "stack_ring_b".to_string()
            ]]
        );
        for kind in oracle.hangs.keys() {
            assert!(
                kinds.is_a(kind, "stack_ring_a"),
                "{kind} reaches the reported cycle"
            );
        }
    }
}

#[test]
fn generated_kinds_drive_model_queries() {
    let mut kinds = KindRegistry::new();
    assert!(generated::register(&mut kinds).is_empty());
    let before = kinds.clone();
    assert_eq!(
        generated::register(&mut kinds).len(),
        generated::KINDS.len(),
        "registering again refuses every kind, as OpenUSD refuses them"
    );
    assert_eq!(kinds, before, "the first registrations stand");
    let mut store = InMemoryStore::default();
    let path = store.path("/Model");
    let kind = store.tokens.intern("kind");
    let leaf = store.tokens.intern("stack_leaf");
    let mut layer = Layer::new(LayerId(1));
    layer.insert_prim(
        path,
        PrimSpec::def().with_field(kind, FieldValue::Value(Value::Token(leaf))),
    );
    store.insert_layer(layer);
    let stage = Stage::compose(&mut store, LayerId(1), StageOptions::default());
    let scene = Scene::new(&stage, &store).with_kinds(&kinds);
    assert!(
        scene.is_model(path),
        "generated custom kinds participate in model queries"
    );
}
